import{_ as e,o as s,a as i,a2 as a}from"./chunks/framework.DCcmcJcL.js";const g=JSON.parse('{"title":"Agent Skills","description":"","frontmatter":{},"headers":[],"relativePath":"ai/agent-skills.md","filePath":"ai/agent-skills.md","lastUpdated":1789464754000}'),o={name:"ai/agent-skills.md"};function d(l,t,n,r,h,c){return s(),i("div",null,t[0]||(t[0]=[a(`<h1 id="agent-skills" tabindex="-1">Agent Skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to &quot;Agent Skills&quot;">​</a></h1><p>Agent skills are folders of Markdown instructions that a coding agent loads when a task matches them: a <code>SKILL.md</code> with a name and a description of when to use it, plus reference files the agent opens only when it needs the detail. Bagisto&#39;s skills carry the conventions a reviewer would otherwise send back, from how packages, themes and tests are built to the coding rules Pint doesn&#39;t enforce. They are published under <code>skills/</code> in the <a href="https://github.com/bagisto/agent-skills" target="_blank" rel="noreferrer"><code>bagisto/agent-skills</code></a> repository, not as a Composer or npm package, and you install them into your project with one of the tools below.</p><h2 id="the-skills" tabindex="-1">The Skills <a class="header-anchor" href="#the-skills" aria-label="Permalink to &quot;The Skills&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Use it when</th></tr></thead><tbody><tr><td><code>bagisto-coding-standards</code></td><td>Writing or reviewing any Bagisto PHP or Blade</td></tr><tr><td><code>bagisto-package-development</code></td><td>Creating a package: providers, migrations, models, repositories, routes, menus, ACL, configuration</td></tr><tr><td><code>bagisto-datagrid-development</code></td><td>Building an admin listing page</td></tr><tr><td><code>bagisto-attribute-development</code></td><td>Working with attributes, attribute families and EAV values</td></tr><tr><td><code>bagisto-theme-sections</code></td><td>Working on the Appearance area: theme sections, the editor and its preview</td></tr><tr><td><code>bagisto-data-transfer</code></td><td>Adding or changing an import</td></tr><tr><td><code>bagisto-payment-method-development</code></td><td>Building a payment method</td></tr><tr><td><code>bagisto-shipping-method-development</code></td><td>Building a shipping method</td></tr><tr><td><code>bagisto-product-type-development</code></td><td>Building a product type</td></tr><tr><td><code>bagisto-shop-theme-development</code></td><td>Creating a storefront theme</td></tr><tr><td><code>bagisto-admin-theme-development</code></td><td>Creating an admin theme</td></tr><tr><td><code>bagisto-shop-advance-theme-development</code></td><td>Building a storefront feature on the advanced theme workflow</td></tr><tr><td><code>bagisto-pest-testing</code></td><td>Writing Pest tests</td></tr><tr><td><code>bagisto-playwright-testing</code></td><td>Writing or debugging Playwright end-to-end tests</td></tr><tr><td><code>bagisto-change-verification</code></td><td>Running the checks before calling a change done</td></tr><tr><td><code>bagisto-code-review</code></td><td>Reviewing a change or a pull request</td></tr><tr><td><code>bagisto-git-workflow</code></td><td>Branches, commits, CHANGELOG entries and pull requests</td></tr><tr><td><code>bagisto-documentation</code></td><td>Writing Bagisto documentation</td></tr><tr><td><code>bagisto-api-develop</code></td><td>Working inside the <code>bagisto/bagisto-api</code> package</td></tr><tr><td><code>bagisto-api-shop</code></td><td>Building a storefront or customer app on the Shop API</td></tr><tr><td><code>bagisto-api-admin</code></td><td>Building a back-office app on the Admin API</td></tr></tbody></table><p>The three API skills sit together under <code>skills/api-platform-development/</code>. The repository changes often, so the <code>--list</code> option of either tool below shows what it holds today.</p><h2 id="agents-md-and-claude-md" tabindex="-1">AGENTS.md and CLAUDE.md <a class="header-anchor" href="#agents-md-and-claude-md" aria-label="Permalink to &quot;AGENTS.md and CLAUDE.md&quot;">​</a></h2><p>Bagisto ships three instruction files that coding agents read:</p><table tabindex="0"><thead><tr><th>File</th><th>For</th></tr></thead><tbody><tr><td><code>AGENTS.md</code></td><td>Agents that follow the AGENTS.md convention</td></tr><tr><td><code>CLAUDE.md</code></td><td>Claude Code</td></tr><tr><td><code>.github/copilot-instructions.md</code></td><td>GitHub Copilot</td></tr></tbody></table><p><code>AGENTS.md</code> and <code>CLAUDE.md</code> map each kind of work to the skill to load, and give the repository layout, the test and code style commands, and the PostgreSQL compatibility rules. <code>AGENTS.md</code> also lists the files not to edit. Both expect the skills under <code>.claude/skills/&lt;name&gt;/SKILL.md</code>. The skills aren&#39;t committed with Bagisto, though: its <code>.gitignore</code> excludes <code>.claude/</code>, <code>.agents/</code>, <code>.cursor/</code>, <code>boost.json</code> and <code>skills-lock.json</code>. Install them into your checkout with one of the two tools below.</p><p>The <code>bagisto/agent-skills</code> repository keeps an <code>AGENTS.md</code> of its own as well, which <code>bin/build-agents.sh</code> assembles for a Bagisto release line from the fragments in <code>rules/</code>. Start there if your team maintains shared agent instructions.</p><h2 id="installing-with-the-skills-cli" tabindex="-1">Installing with the Skills CLI <a class="header-anchor" href="#installing-with-the-skills-cli" aria-label="Permalink to &quot;Installing with the Skills CLI&quot;">​</a></h2><p>The <a href="https://skills.sh" target="_blank" rel="noreferrer"><code>skills</code></a> CLI runs through <code>npx</code> and needs Node.js 22.20 or newer. Run it at the root of your Bagisto application, so the skills install for that project:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto-coding-standards</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto-package-development</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;*&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude-code</span></span></code></pre></div><p><code>--list</code> shows the skills without installing anything, and <code>--skill</code> installs the ones you name; <code>--skill &#39;*&#39;</code> with <code>-a</code> installs every skill for the agent you name. <code>--all</code> is short for <code>--skill &#39;*&#39; --agent &#39;*&#39; -y</code>: every skill, for every agent the CLI supports, without prompting. The CLI keeps one copy of each skill in <code>.agents/skills/</code> and symlinks it into other agents&#39; folders, such as <code>.claude/skills/</code>. It records what it installed in <code>skills-lock.json</code>.</p><table tabindex="0"><thead><tr><th>Option</th><th>Effect</th></tr></thead><tbody><tr><td><code>-a, --agent &lt;agent&gt;</code></td><td>Installs for the named agent, for example <code>claude-code</code> or <code>cursor</code></td></tr><tr><td><code>-y, --yes</code></td><td>Skips the prompts</td></tr><tr><td><code>-g, --global</code></td><td>Installs into your home directory, for every project</td></tr><tr><td><code>--copy</code></td><td>Copies the files instead of symlinking them</td></tr></tbody></table><p>Update the installed skills with <code>npx skills update</code>, see them with <code>npx skills list</code>, and remove one with <code>npx skills remove &lt;name&gt;</code>.</p><h2 id="installing-with-laravel-boost" tabindex="-1">Installing with Laravel Boost <a class="header-anchor" href="#installing-with-laravel-boost" aria-label="Permalink to &quot;Installing with Laravel Boost&quot;">​</a></h2><p>Bagisto requires <code>laravel/boost</code> as a development dependency, and Boost can fetch skills from a GitHub repository.</p><ol><li><p>Set Boost up once and choose the agents you use:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boost:install</span></span></code></pre></div></li><li><p>Add the skills:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boost:add-skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill=bagisto-coding-standards</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill=bagisto-package-development</span></span></code></pre></div></li></ol><p><code>boost:add-skill</code> first runs a security audit on the selected skills, unless you pass <code>--skip-audit</code>, and asks before installing any it rates risky; a non-interactive run installs them without asking. It then downloads each skill into <code>.ai/skills/&lt;name&gt;</code> and runs <code>boost:update</code>, which writes the skills into the folder of every agent <code>boost:install</code> set up. <code>--list</code> shows the available skills, <code>--all</code> installs all of them, and <code>--force</code> replaces skills that are already installed.</p><h2 id="things-to-watch" tabindex="-1">Things to Watch <a class="header-anchor" href="#things-to-watch" aria-label="Permalink to &quot;Things to Watch&quot;">​</a></h2><ul><li><strong>Boost needs <code>boost:install</code> first.</strong> Without it, <code>boost:add-skill</code> still downloads the skills into <code>.ai/skills</code>, but the update that copies them to your agents fails without a message.</li><li><strong>Boost lists a nested reference as a skill.</strong> It treats every <code>SKILL.md</code> in the repository as a skill, so its list also shows <code>bagisto-theme-testing</code>, which is a reference inside <code>bagisto-shop-advance-theme-development</code>.</li><li><strong>Bagisto&#39;s <code>.gitignore</code> doesn&#39;t exclude <code>.ai/</code>.</strong> Decide whether Boost&#39;s copies belong in your repository.</li><li><strong>Skills aren&#39;t pinned to a release.</strong> <code>npx skills add</code> takes the repository&#39;s default branch, so a Bagisto 2.4 project and a Bagisto 2.5 project get the same text. Where the releases differ, a skill says which release a rule applies to.</li><li><strong>The API package skill&#39;s install steps are older.</strong> <code>bagisto-api-develop</code> describes installing <code>bagisto/bagisto-api</code> on Bagisto 2.3.8 with pinned API Platform versions. Follow <a href="./../api/installation.html">Installation</a> instead.</li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./llms-txt.html">llms.txt</a>: this documentation as plain text for AI tools.</li><li><a href="https://api-docs.bagisto.com/api/build-with-ai/" target="_blank" rel="noreferrer">Build with AI</a>: the REST and GraphQL reference&#39;s own <code>llms.txt</code> and optional MCP server.</li><li><a href="https://github.com/bagisto/bagisto/blob/master/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a>: the contribution rules <code>bagisto-git-workflow</code> and <code>bagisto-code-review</code> follow.</li></ul>`,24)]))}const k=e(o,[["render",d]]);export{g as __pageData,k as default};
